MOD = 1000000007

def count_ways(n, maze):
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if maze[i][j] == 'o':
                dp[i][j] = 1
            elif dp[i][j]:
                dp[i][j] += 2
            else:
                dp[i][j] = 0

    for k in range(2, n):
        for i in range(n):
            for j in range(n):
                if not dp[i][j]:
                    continue
                dp[i][j] += min(dp[(i-1)%n][j], dp[(i+1)%n][j], dp[i][(j-1)%n], dp[i][(j+1)%n])
                dp[i][j] %= MOD

    return sum(sum(x) for x in dp) % MOD

