from math import comb

def count_paintings(n, m, k):
    if n == 1 or m == 1:
        return 1
    MOD = 1000000007

    dp = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i == 1 and j == 1:
                continue
            if i == 2:
                dp[j][2] = ((j * comb(all_spots[j], 1)) % MOD + all_spots[j] * dp[j-1][j]) % MOD
            else:
                dp[j][2] = ((j * dp[j+1][2]) % MOD + dp[j-1][j]) % MOD
            if j == 2:
                dp[2][j] = ((2 * dp[1][j-1]) % MOD + dp[3][j]) % MOD
        all_spots = 0
        for i in range(1, n+1):
            all_spots += dp[1][i]
    return dp[1][m] % MOD

