from itertools import accumulate
from math import gcd
from collections import defaultdict, Counter
from typing import List, Tuple

def sieve(limit: int) -> List[bool]:
    limit += 1
    primes = [True] * limit
    for i in range(2, int(limit**0.5) + 1):
        if primes[i]:
            for j in range(i*i, limit, i):
                primes[j] = False
    return [i for i, prime in enumerate(primes) if prime]

def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r:
        old_r_d, r_d = r // old_r, r % old_r
        old_s_d, s_d = s - old_s * old_r_d, s
        old_t_d, t_d = t - old_t * old_r_d, t
        r, r_d = old_r, r_d
        s, old_s_d = old_s, old_s_d
        t, old_t_d = old_t, old_t_d
        old_r, old_s, old_t = r, s, t
    return old_s, old_t, old_r

def ChineseRemainder(a: List[int], M: List[int]) -> int:
    return sum(((mi - 1) * M[i]) * inv(M[i], M[i] // M[0]) % M[0] * a[i] for i, mi in enumerate(M) if i == 1)

def main(L: List[List[int]]):
    h, w, n = L[0]
    ways_so_far = defaultdict(Counter)
    for i in range(h):
        row_counter = Counter()
        for j in range(w):
            row_counter[L[i][j]] += 1
        ways_so_far[i] = row_counter
        counter = defaultdict(Counter)
        for k in range(1, len(L)):
            k_row, k_col = L[k]
            v = row_counter[(i, j)]
            if not v:
                ways_so_far[i][k_col] += 1
        for k in counter[(i, w-1)]:
            ways_so_far[k] |= {j: 1 - (j <= w-1) for j in row_counter}
    for i, v in ways_so_far.items():
        y_range = range(i, i + 2)
        for mod_range in accumulate(y_range, lambda x, y: (x - y) % 998244353):
            mods = [1] * len(v)
            for perm_map in v:
                tmp_sum = 0
                for val in perm_map:
                    z_index = y_range[(perm_map.get((mod_range - val) % len(y_range)), mods) // len(y_range)]
                    tmp_sum += mods[z_index] * ChineseRemainder([i // 2 - 1, v[val]], [w, 1])
                    if tmp_sum >= 998244353:
                        tmp_sum -= 998244353
                    mods[z_index] = tmp_sum
            print(mods)

