from functools import lru_cache
from typing import List

@lru_cache(maxsize=None)
def count_ways(n: int, m: int, col: int) -> int:
    if n * m == 0:
        return 1 if col == 0 else 0

    total_ways = 0
    for next_row in range(max(0, col - 1), min(n, col + 1) + 1):
        total_ways += count_ways(next_row, m - 1, col)

    return total_ways

def mult_h(n: int, mod: int) -> int:
    sum_fac = [0] * (n + 1)
    sum_fac[0], sum_fac[1] = 1, 1
    for i in range(2, n + 1):
        sum_fac[i] = (mod // i) * (sum_fac[i - 1] + sum_fac[i // i])

    return sum_fac[n]

def solve(n: int, m: int, k: int) -> int:
    MODULUS = 10**9 + 7
    return (mult_h(n, MODULUS) * mult_h(m - 1, MODULUS) % MODULUS * count_ways(n, m - 1, 0)) % MODULUS

def main():
    n, m, k = map(int, input().split())
    print(solve(n, m, k))

if __name__ == "__main__":
    main()
