import math

def inversion_expectation(n, m, permutations):
    """
    Calculate the expected number of inversions after m moves on an array of size n.

    :param n: The size of the permutation array.
    :param m: The number of moves to be made.
    :param permutations: A list of integers representing the initial permutation.
    :return: The expected number of inversions after m moves.
    """
    inversions = 0
    for permutation in permutations:
        inversion_count = 0
        for i in range(n - 1):
            for j in range(i + 1, n):
                if permutation[i] > permutation[j]:
                    inversion_count += 1
        inversions += 1 / len(permutations) * inversion_count
    return inversions * math.factorial(n) / (math.factorial(n) * (math.factorial(m + n - 2) - math.factorial(n - 1)))
