from collections import defaultdict

def num_ways(n, k, cells):
    memo = {}
    def dfs(row, col, filled):
        if (row, col, filled) in memo:
            return memo[(row, col, filled)]

        if (not filled):
            memo[(row, col, filled)] = 1
            for x, y in [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]:
                if 1 <= x <= n and 1 <= y <= n:
                    memo[(row, col, filled)] += dfs(x, y, True)
        else:
            # If filled, the number of adjacent 'o's must be even
            filled_count = {(i, j): True for x, y in [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)] if 1 <= x <= n and 1 <= y <= n}
            memo[(row, col, filled)] = (2 ** (k - 2) % 1000000007) if not filled_count[(row, col)] else 0

        return memo[(row, col, filled)]

    return dfs(1, 1, False) % 1000000007

