from itertools import permutations

def rebuild_permutation(perm, cost, reduced_perm):
    reduced_indices = [i for i, p in enumerate(perm) if p in reduced_perm]
    altered_indices = [i for i, p in enumerate(perm) if p in reduced_perm]
    start = bisect.bisect_left(reduced_indices, cost)
    end = bisect.bisect_right(reduced_indices, cost + 1)

    if end - start < len(altered_indices):
        return -1  # Not enough non-overlapping subranges for the cost
    else:
        return perm[reduced_indices[start]:reduced_indices[end]]

