from math import inf

def min_time_to_form_tie(n, k, b, c, contributions):
    if k == 1:
        return b + c * (n - 1)
    if sum(contributions) // k == c and -sum(contributions) // k <= b - (n - 1):
        return (sum(contributions) // k) * c + (-(sum(contributions) // k) + b) * (n - 1)
    dp = [[inf] * (1 << 64) for _ in range(n+1)]
    dp[-1][0] = 0
    min_time = inf

    for i in range(n):
        for mask in range(1 << i):
            if mask == 0:
                continue
            new_mask = mask | (1 << i)
            for j in range(n):
                if new_mask & (1 << j):
                    dp[i][new_mask] = min(dp[i][new_mask], dp[j][mask] + c)
                    dp[j][mask] = min(dp[j][mask], dp[i][new_mask] - b)
        dp[i][mask] = min(dp[i][mask], dp[i-1][mask] + c)
        dp[i][mask] = min(dp[i][mask], dp[i-1][mask] - b)
        new_min = min(dp[i][mask] for mask in range(1 << i) if ((1 << i) - mask) & mask)
        min_time = min(min_time, new_min)

    return min_time

