def modpow(a, b, m):
    result = 1
    a = a % m
    while b > 0:
        if b & 1:
            result = (result * a) % m
        b = b >> 1
        a = (a * a) % m
    return result

def balanced_lattice_answer(h, w, n, placements):
    zero_ways = [[0] * w for _ in range(h + 1)]
    for r1, c1, r2, c2 in placements:
        zero_ways[r1][c1] += 1
        zero_ways[r2][c2] += 1
    for i in range(1, h + 1):
        for j in range(1, w + 1):
            zero_ways[i][j] += zero_ways[i][j-1] + zero_ways[i-1][j] - zero_ways[i-1][j-1]
    return modpow(4, w * h - 2 * sum(zero_ways[1][1:]), 998244353)

