from itertools import product

def find_ways(n, m, k, colors):
    mod = 1000000007
    color_combinations = []

    for c in range(1, k+1):
        for comb in product((0, 1), repeat=k):
            if sum(comb) == 1:
                color_combinations.append(frozenset([(c - 1, cons) for cons in comb]))

    memo = {}

    def dp(i, j, visited):
        if (i, j, frozenset(visited)) in memo:
            return memo[(i, j, frozenset(visited))]

        if i == n or j == m:
            return 1

        total = 0

        for di, dj in [(0, 1), (1, 0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                if (ni, nj) not in visited:
                    for cell in color_combinations:
                        coordinates = [tuple(color) for color in cell]
                        if frozenset(cell).intersection(visited) == frozenset():
                            new_visited = tuple(filter(lambda x: x not in visited, coordinates))
                            total += dp(ni, nj, new_visited)
                            total %= mod

        memo[(i, j, frozenset(visited))] = total
        return total

    return dp(0, 0, ())
