import sys

def get_min_time_needed(n, k, b, c, nums):
    max_contrib = max(nums)
    min_num_contrib = k - 1
    max_contrib -= min_num_contrib
    remaining = n - k
    total_time = max_contrib * (n - 1)
    if remaining == 0:
        return total_time
    for i in range(n):
        if nums[i] <= max_contrib or nums[i] == max_contrib:
            continue
        if nums[i] == max_contrib:
            num_blogs = (nums[0] - (i + 1) * c) // b + 1
            if nums[i] % c == n % c:
                num_blogs = num_blogs - 1
            valid = True
            for j in range(i + 1, n):
                if nums[j] == max_contrib:
                    total_time += 2 * num_blogs + (min_num_contrib if j == n else c * (j + 1 - n))
                    num_blogs = 0
                else:
                    if nums[j] > min_num_contrib and nums[j] - (j + 1) * c - (i + 1) * c < c:
                        valid = False
                        break
                    if nums[j] >= nums[i] and nums[j] - (j + 1) * c < c:
                        if (j + 1) % c == n % c:
                            total_time += num_blogs + c * (j + 1 - n)
                        else:
                            num_blogs += remaining // c
                        total_time += remaining % c * b + c
                    if (j + 1) % c == n % c:
                        if (nums[i] + 5 < nums[j] or nums[j] - nums[i] + 10 > 2 * c or (i != 0 and nums[i] - nums[i-1] + 10 > 2 * c)):
                            valid = False
                            break
                    else:
                        if (nums[i] + 5 < nums[j] or nums[j] - nums[i] + 10 > 2 * c):
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                return total_time
    return -1

