import collections

def is_reachable_and_time(n, arcs, queries):
    indegree = [0] * n
    state = collections.defaultdict(str)
    state[0] = 'B'

    for v in range(1, n):
        indegree[v] = int(arcs[v-1][state[v-1]])

    for query in queries:
        if state[query[0]] == 'B':
            if indegree[query[0]] != int(arcs[query[0]-1][query[1]]):
                return -1  # not reachable
            if state[int(arcs[query[0]-1][query[1]])] == 'B':
                state[query[0]] = 'R'
            else:
                state[query[0]] = 'B'
        else:
            if state[int(arcs[query[0]-1][query[1]])] != 'B':
                return -1  # not reachable
            if state[query[0]] == 'B':
                state[query[0]] = 'R'
            else:
                state[query[0]] = 'B'
        print(state[max(state)])

