def balance_dominoes(h, w, n, dominoes):
    balance = [0] * (h + 2)  # We add two extra rows for simplicity
    overlaps = [(0, 0, 0)]  # To count overlaps in each row

    for r1, c1, r2, c2 in dominoes:
        if balance[r1] == 1 and balance[r2] == -1:
            if not overlaps or (abs(overlaps[0][0] - r1) > 1 or abs(overlaps[0][1] - c1) > 1):
                return 0
            else:
                overlaps.append((overlaps[0][2], r1, c1, r2, c2))
        elif balance[r1] == 1 or balance[r2] == 1:
            return 0
        balance[r1] = -balance[r1]
        balance[r2] = -balance[r2]

    extra = 1
    for r in range(1, h + 2):
        if balance[r] == 1:
            extra = (extra * (w + 1 - l) // r) % 998244353  # Polynomial growth
        elif balance[r] == -1:
            extra = (extra * l // r) % 998244353  # Polynomial growth
        l = r
    return extra

h, w, n = map(int, input().split())
