import sys
import itertools

def max_stability(n, k, walls):
    original_stab = k
    for combo in itertools.product([1, 0], repeat=n):
        if sum(combo) == 0:
            continue
        new_stab = k
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if walls[i][j]:
                    new_stab *= combo[i] * combo[j]
        original_stab = max(original_stab, new_stab)
    return original_stab

